const config = $('Config').item.json;
const raw = $('Solicitud entrante').item.json;
const body = raw.body || raw;
return [{ json: {
  model: config.model,
  vigencia_dias: config.vigencia_dias,
  lista_precios_json: config.lista_precios_json,
  system_prompt: config.system_prompt,
  nombre_cliente: body.nombre_cliente || body.nombre || 'cliente',
  empresa: body.empresa || '',
  mensaje_solicitud: body.mensaje_solicitud || body.mensaje || ''
} }];

const raw = $json.content?.[0]?.text || '{}';
let d;
try { d = JSON.parse(raw); } catch (e) {
  d = { asunto: 'Cotizacion', nombre_cliente: 'cliente', empresa: '', items: [], total_mensual: 0, total_unico: 0, vigencia_dias: 10, notas: 'Error al generar, revisar manualmente.', items_sin_precio: ['todos'], siguiente_paso: 'Revisar con ejecutivo comercial' };
}
const itemsSinPrecio = d.items_sin_precio || [];
const necesitaRevision = itemsSinPrecio.length > 0;
return [{ json: {
  cotizacion: d,
  necesita_revision: necesitaRevision,
  items_sin_precio: itemsSinPrecio
} }];
